import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, transaction, toJob, HEARTBEAT_MAX_AGE_MS, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError {
  field: string;
  message: string;
}

class ApiError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...headers });
  res.end(text);
}

function sendError(res: ServerResponse, err: ApiError, headers: Record<string, string> = {}): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  send(res, err.status, { error }, headers);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooLarge = true;
      else chunks.push(c);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, created_at, updated_at, run_after, idempotency_key, payload)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);
const selectHeartbeat = db.prepare('SELECT at FROM heartbeat WHERE id = 1');

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

function checkInt(value: unknown, field: string, min: number, max: number, errors: FieldError[]): number | undefined {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    errors.push({ field, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  if (!Number.isInteger(value) || value < min || value > max) {
    errors.push({ field, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  return value;
}

function validate(req: IncomingMessage, body: { text: string; tooLarge: boolean }): { payload: Payload; key: string | undefined } {
  const errors: FieldError[] = [];
  const rawKey = req.headers['idempotency-key'];
  let key: string | undefined;
  if (rawKey !== undefined) {
    const k = Array.isArray(rawKey) ? rawKey.join(',') : rawKey;
    if (!KEY_RE.test(k)) errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
    else key = k;
  }

  const ct = req.headers['content-type'];
  const mediaType = typeof ct === 'string' ? ct.split(';')[0]!.trim().toLowerCase() : '';
  let payload: Payload | undefined;
  if (mediaType !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (body.tooLarge) {
    errors.push({ field: 'body', message: 'body is too large' });
  } else {
    let data: unknown;
    let parsed = true;
    try {
      data = JSON.parse(body.text);
    } catch {
      parsed = false;
      errors.push({ field: 'body', message: 'body must be valid JSON' });
    }
    if (parsed) {
      if (typeof data !== 'object' || data === null || Array.isArray(data)) {
        errors.push({ field: 'body', message: 'body must be a JSON object' });
      } else {
        const obj = data as Record<string, unknown>;
        for (const k of Object.keys(obj)) {
          if (k !== 'input' && k !== 'steps' && k !== 'failAttempts') errors.push({ field: k, message: 'unknown field' });
        }
        let input: string | undefined;
        if (!Object.hasOwn(obj, 'input')) {
          errors.push({ field: 'input', message: 'is required' });
        } else if (typeof obj.input !== 'string') {
          errors.push({ field: 'input', message: 'must be a string' });
        } else if (obj.input.length < 1 || obj.input.length > 1000) {
          errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
        } else if (obj.input.trim() === '') {
          errors.push({ field: 'input', message: 'must not be only whitespace' });
        } else {
          input = obj.input;
        }
        const steps = Object.hasOwn(obj, 'steps') ? checkInt(obj.steps, 'steps', 1, 20, errors) : 5;
        const failAttempts = Object.hasOwn(obj, 'failAttempts') ? checkInt(obj.failAttempts, 'failAttempts', 0, 5, errors) : 0;
        if (input !== undefined && steps !== undefined && failAttempts !== undefined) payload = { input, steps, failAttempts };
      }
    }
  }
  if (errors.length > 0 || !payload) {
    throw new ApiError(400, 'invalid_request', 'The request is invalid.', errors);
  }
  return { payload, key };
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const { payload, key } = validate(req, body);
  const canonical = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);
  const outcome = transaction(db, () => {
    if (key !== undefined) {
      const existing = selectByKey.get(key) as JobRow | undefined;
      if (existing) {
        if (existing.payload !== canonical) {
          throw new ApiError(409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        }
        return { status: 200, row: existing };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    insertJob.run(id, payload.input, payload.steps, payload.failAttempts, now, now, key ?? null, key !== undefined ? canonical : null);
    return { status: 201, row: selectById.get(id) as unknown as JobRow };
  });
  send(res, outcome.status, toJob(outcome.row));
}

const ROUTES: { pattern: RegExp; methods: string[] }[] = [
  { pattern: /^\/$/, methods: ['GET'] },
  { pattern: /^\/health$/, methods: ['GET'] },
  { pattern: /^\/api\/jobs$/, methods: ['GET', 'POST'] },
  { pattern: /^\/api\/jobs\/[^/]+$/, methods: ['GET'] },
];

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  let pathname: string;
  try {
    pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  } catch {
    pathname = '/__invalid__';
  }
  const method = req.method === 'HEAD' ? 'GET' : (req.method ?? 'GET');
  const route = ROUTES.find((r) => r.pattern.test(pathname));
  if (!route) throw new ApiError(404, 'not_found', 'Not found.');
  if (!route.methods.includes(method)) {
    req.resume();
    sendError(res, new ApiError(405, 'method_not_allowed', 'Method not allowed.'), { allow: route.methods.join(', ') });
    return;
  }

  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    const hb = selectHeartbeat.get() as { at: number } | undefined;
    const up = hb !== undefined && Date.now() - Number(hb.at) <= HEARTBEAT_MAX_AGE_MS;
    send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') return createJob(req, res);
    const rows = selectAll.all() as unknown as JobRow[];
    send(res, 200, { jobs: rows.map(toJob) });
    return;
  }
  let id: string;
  try {
    id = decodeURIComponent(pathname.slice('/api/jobs/'.length));
  } catch {
    throw new ApiError(404, 'not_found', 'Job not found.');
  }
  const row = selectById.get(id) as JobRow | undefined;
  if (!row) throw new ApiError(404, 'not_found', 'Job not found.');
  send(res, 200, toJob(row));
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    if (e instanceof ApiError) {
      req.resume();
      sendError(res, e);
    } else {
      console.error(e);
      sendError(res, new ApiError(500, 'internal_error', 'Internal server error.'));
    }
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    try {
      db.close();
    } catch {
      // ignore
    }
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => {
    server.closeAllConnections();
  }, 1000).unref();
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

