import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, transaction, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const LEASE_MS = 2000;
const POLL_MS = 100;
const HEARTBEAT_MS = 500;

const db = openDatabase();
let stopping = false;
let wake: (() => void) | undefined;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    wake?.();
  });
}

const heartbeatStmt = db.prepare('INSERT INTO heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at');
function heartbeat(): void {
  try {
    heartbeatStmt.run(Date.now());
  } catch (e) {
    console.error('heartbeat failed', e);
  }
}

const selectNext = db.prepare(
  `SELECT * FROM jobs
   WHERE (status = 'queued' AND run_after <= ?1) OR (status = 'running' AND lease_until < ?1)
   ORDER BY seq ASC LIMIT 1`,
);
const startAttempt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, output = NULL, error = NULL,
     lease_until = ?, updated_at = ? WHERE id = ?`,
);
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const stepDone = db.prepare(`UPDATE jobs SET progress = ?, lease_until = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const completeJob = db.prepare(
  `UPDATE jobs SET status = 'completed', progress = steps, output = ?, error = NULL, lease_until = 0, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const retryJob = db.prepare(
  `UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, lease_until = 0, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const failJob = db.prepare(
  `UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?, lease_until = 0, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const releaseJob = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, lease_until = 0, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);

function claim(): JobRow | undefined {
  return transaction(db, () => {
    const now = Date.now();
    const row = selectNext.get(now) as JobRow | undefined;
    if (!row) return undefined;
    startAttempt.run(now + LEASE_MS, new Date(now).toISOString(), row.id);
    return selectById.get(row.id) as unknown as JobRow;
  });
}

async function process_(job: JobRow): Promise<void> {
  const iso = () => new Date().toISOString();
  const attempt = job.attempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Hand the interrupted attempt back so the next worker run starts it fresh.
      releaseJob.run(iso(), job.id);
      return;
    }
    if (step === 1 && attempt <= job.fail_attempts) {
      if (attempt >= MAX_ATTEMPTS) failJob.run('transient failure', iso(), job.id);
      else retryJob.run(Date.now() + RETRY_DELAY_MS, iso(), job.id);
      return;
    }
    if (step < job.steps) stepDone.run(step, Date.now() + LEASE_MS, iso(), job.id);
  }
  completeJob.run(job.input.toUpperCase(), iso(), job.id);
}

heartbeat();
const hbTimer = setInterval(heartbeat, HEARTBEAT_MS);
console.log('worker started');

while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claim();
  } catch (e) {
    console.error('claim failed', e);
  }
  if (job) {
    try {
      await process_(job);
    } catch (e) {
      console.error('processing failed', e);
    }
    continue;
  }
  await new Promise<void>((resolve) => {
    wake = resolve;
    setTimeout(resolve, POLL_MS);
  });
  wake = undefined;
}

clearInterval(hbTimer);
try {
  db.close();
} catch {
  // ignore
}
process.exit(0);

